  const labels=identifiers.length?identifiers.slice(0,3).map(shortLabel).join(' · ')+(identifiers.length>3?`<details><summary>${identifiers.length-3} more</summary>${identifiers.slice(3).map(esc).join(' · ')}</details>`:''):`<span class="muted">${sampleLabel?'Sample labels':'Identifiers'} not recorded</span>`;
