 if(!state.editor||!canEdit())return;capture();const p=state.editor.input,refs=p.participants??p.donors;
 if(action==='calculate-phase'){if(!['decapitation','sampling'].includes(id))throw new Error('Choose a timing event.');const [clock]=timingKeys(state.editor.kind==='sample',id);state.editor.phasePreviews[id]={result:calculatePhase(p[clock],p.entrainment),fingerprint:phaseFingerprint(p,state.editor.kind==='sample',id)}}
 else if(action==='apply-phase'){const preview=state.editor.phasePreviews[id];if(!preview||preview.result.status!=='calculated')throw new Error('Calculate the phase first.');if(preview.fingerprint!==phaseFingerprint(p,state.editor.kind==='sample',id))throw new Error('Timing or reference changed. Calculate the phase again before applying.');const [,phase,basis,origin]=timingKeys(state.editor.kind==='sample',id);p[phase]=String(preview.result.value);p[basis]=preview.result.basis;p[origin]='calculated';delete state.editor.phasePreviews[id]}
 else if(action==='calculate-duration'){const result=calculateEntrainmentDuration(p.entrainment,p.decapitation_at||(state.editor.kind==='sample'?p.collection_at:p.sampling_at));state.editor.durationMessage=result.reason;if(result.days==null)throw new Error(result.reason);p.entrainment.duration_days=result.days;p.entrainment.duration_basis=result.basis}
 else if(action==='use-light-history'){const sid=container.querySelector('#exp-light-history')?.value,history=entrainmentHistoryCandidates(data(),refs.filter(x=>x.link_status==='confirmed').map(x=>x.mouse_sid),p.event_date).find(x=>x.event_id===sid);if(!history)throw new Error('Choose and verify a light history record.');p.entrainment={...p.entrainment,light_event_id:history.event_id,scheme:history.protocol||'unknown',period_hours:Number.isFinite(Number(history.cycle_hours))&&Number(history.cycle_hours)>0?Number(history.cycle_hours):null,timezone:history.timezone||p.entrainment.timezone};state.editor.phasePreviews={}}
 else if(action==='add-mouse'||action==='resolve'){const sid=container.querySelector(action==='add-mouse'?'#exp-add-mouse':`[data-resolve="${Number(id)}"]`).value.trim(),m=mouse(sid);if(!m)throw new Error('Choose the exact mouse SID from the suggestions.');if(refs.some(r=>r.mouse_sid===sid))throw new Error('This animal is already linked.');const ref={mouse_sid:sid,raw_identifier:action==='resolve'?refs[Number(id)].raw_identifier:(m.physical_tag||sid),link_status:'confirmed',candidate_sids:[],role:action==='resolve'?refs[Number(id)].role:null,notes:action==='resolve'?refs[Number(id)].notes:null};if(action==='resolve')refs[Number(id)]=ref;else refs.push(ref)}
 else if(action==='add-unresolved'){const raw=container.querySelector('#exp-unresolved').value.trim();if(!raw)throw new Error('Enter the original animal identifier.');refs.push({mouse_sid:null,raw_identifier:raw,link_status:'unresolved',candidate_sids:[],role:null,notes:null})}
